    {"id": "chalukya", "year": 543, "title": "Early Chalukya power at Badami", "fact": "Pulakeshin I established a major centre of Chalukya power at Badami around the middle of the sixth century.", "region": "india", "topic": "empires", "place": {"name": "Badami", "lat": 15.92, "lon": 75.68}, "approximate": true},
    {"id": "harsha", "year": 606, "title": "Harsha begins reign", "fact": "Harsha became ruler in northern India. Accounts of his reign include the work of the writer Bana and the traveller Xuanzang.", "region": "india", "topic": "leaders", "place": {"name": "Kannauj", "lat": 27.05, "lon": 79.91}, "approximate": false},
    {"id": "ellora", "year": 750, "title": "Kailasa temple at Ellora", "fact": "The rock-cut Kailasa temple was created in the eighth century, commonly associated with the Rashtrakuta ruler Krishna I.", "region": "india", "topic": "culture", "place": {"name": "Ellora", "lat": 20.03, "lon": 75.18}, "approximate": true},
    {"id": "brihadisvara", "year": 1010, "title": "Brihadisvara temple consecrated", "fact": "Rajaraja I's great temple at Thanjavur was consecrated in 1010. Its inscriptions record donations and administration.", "region": "india", "topic": "culture", "place": {"name": "Thanjavur", "lat": 10.79, "lon": 79.14}, "approximate": false},
    {"id": "khajuraho", "year": 1050, "title": "Khajuraho temples", "fact": "Chandella rulers supported the construction of temples at Khajuraho, mainly between the tenth and eleventh centuries.", "region": "india", "topic": "culture", "place": {"name": "Khajuraho", "lat": 24.85, "lon": 79.92}, "approximate": true},
    {"id": "bhaskara", "year": 1150, "title": "Bhaskara II's Siddhanta Shiromani", "fact": "Bhaskara II composed the Siddhanta Shiromani, a work covering arithmetic, algebra and astronomy.", "region": "india", "topic": "science", "place": {"name": "Karnataka", "lat": 16.83, "lon": 75.71}, "approximate": false},
    {"id": "qutb", "year": 1220, "title": "Qutb Minar's early construction", "fact": "The Qutb Minar was built in stages under early Delhi sultans and later repaired and altered. Much of its early structure dates to the thirteenth century.", "region": "india", "topic": "culture", "place": {"name": "Delhi", "lat": 28.61, "lon": 77.21}, "approximate": true},
    {"id": "konark", "year": 1250, "title": "Sun Temple at Konark", "fact": "The Sun Temple at Konark was built under the Eastern Ganga ruler Narasimhadeva I in the thirteenth century.", "region": "india", "topic": "culture", "place": {"name": "Konark", "lat": 19.89, "lon": 86.09}, "approximate": true},
    {"id": "kabir", "year": 1450, "title": "Poetry of Kabir", "fact": "Kabir's verses circulated in northern India around the fifteenth century, questioning religious divisions and emphasising devotion. His life dates are uncertain.", "region": "india", "topic": "culture", "place": {"name": "Varanasi", "lat": 25.32, "lon": 82.97}, "approximate": true},
    {"id": "nanak", "year": 1469, "title": "Guru Nanak born", "fact": "Guru Nanak was born at Talwandi, now Nankana Sahib in Pakistan. His teachings became foundational to Sikh tradition.", "region": "india", "topic": "leaders", "place": {"name": "Nankana", "lat": 31.45, "lon": 73.71}, "approximate": false},
    {"id": "sher-shah", "year": 1540, "title": "Sher Shah defeats Humayun", "fact": "Sher Shah defeated Humayun at Kannauj and established Sur rule in northern India. Humayun later regained the Mughal throne.", "region": "india", "topic": "conflict", "place": {"name": "Kannauj", "lat": 27.05, "lon": 79.91}, "approximate": false},
    {"id": "fatehpur", "year": 1571, "title": "Fatehpur Sikri developed", "fact": "Akbar developed Fatehpur Sikri as a Mughal capital in the 1570s, with palaces, administrative buildings and religious monuments.", "region": "india", "topic": "culture", "place": {"name": "Fatehpur", "lat": 27.09, "lon": 77.66}, "approximate": true},
    {"id": "haldighati", "year": 1576, "title": "Battle of Haldighati", "fact": "Mughal forces led by Man Singh fought Maharana Pratap's forces at Haldighati. Resistance and campaigning in Mewar continued afterward.", "region": "india", "topic": "conflict", "place": {"name": "Haldighati", "lat": 24.89, "lon": 73.71}, "approximate": false},
    {"id": "adi-granth", "year": 1604, "title": "Adi Granth installed at Amritsar", "fact": "Guru Arjan compiled the Adi Granth, which was installed at the Harmandir Sahib in Amritsar. It became the basis of the Guru Granth Sahib.", "region": "india", "topic": "culture", "place": {"name": "Amritsar", "lat": 31.63, "lon": 74.87}, "approximate": false},
    {"id": "saraighat", "year": 1671, "title": "Battle of Saraighat", "fact": "Ahom forces led by Lachit Borphukan defeated Mughal forces near Guwahati, using the Brahmaputra's river geography.", "region": "india", "topic": "conflict", "place": {"name": "Guwahati", "lat": 26.18, "lon": 91.74}, "approximate": false},
    {"id": "khalsa", "year": 1699, "title": "Khalsa established", "fact": "Guru Gobind Singh established the Khalsa at Anandpur Sahib, a major development in Sikh religious and community life.", "region": "india", "topic": "society", "place": {"name": "Anandpur", "lat": 31.24, "lon": 76.5}, "approximate": false},
    {"id": "panipat-third", "year": 1761, "title": "Third Battle of Panipat", "fact": "Ahmad Shah Durrani's forces defeated a Maratha army near Panipat. The battle caused heavy losses and changed regional power relations.", "region": "india", "topic": "conflict", "place": {"name": "Panipat", "lat": 29.39, "lon": 76.97}, "approximate": false},
    {"id": "atmiya", "year": 1815, "title": "Atmiya Sabha founded", "fact": "Rammohan Roy founded the Atmiya Sabha in Calcutta as a forum for religious and social discussion.", "region": "india", "topic": "society", "place": {"name": "Kolkata", "lat": 22.57, "lon": 88.36}, "approximate": false},
    {"id": "medical-college", "year": 1835, "title": "Calcutta Medical College founded", "fact": "Calcutta Medical College was established to teach medicine through a curriculum based on European medical science.", "region": "india", "topic": "science", "place": {"name": "Kolkata", "lat": 22.57, "lon": 88.36}, "approximate": false},
    {"id": "phule-school", "year": 1848, "title": "Phules open a school for girls", "fact": "Savitribai and Jyotirao Phule opened a school for girls in Pune, challenging barriers to education.", "region": "india", "topic": "society", "place": {"name": "Pune", "lat": 18.52, "lon": 73.86}, "approximate": false},
    {"id": "widow-remarriage", "year": 1856, "title": "Hindu Widows' Remarriage Act", "fact": "A law in British India recognised the remarriage of Hindu widows. Ishwar Chandra Vidyasagar was an important advocate of the reform.", "region": "india", "topic": "society", "place": {"name": "Kolkata", "lat": 22.57, "lon": 88.36}, "approximate": false},
    {"id": "universities-india", "year": 1857, "title": "Universities in Calcutta, Bombay and Madras", "fact": "Universities were established in Calcutta, Bombay and Madras, expanding a new system of examinations and higher education in British India.", "region": "india", "topic": "culture", "place": {"name": "Kolkata", "lat": 22.57, "lon": 88.36}, "approximate": false},
    {"id": "tagore-born", "year": 1861, "title": "Rabindranath Tagore born", "fact": "Rabindranath Tagore was born in Calcutta. He became a writer, composer, artist and educator.", "region": "india", "topic": "leaders", "place": {"name": "Kolkata", "lat": 22.57, "lon": 88.36}, "approximate": false},
    {"id": "vivekananda", "year": 1893, "title": "Vivekananda at Chicago", "fact": "Swami Vivekananda addressed the World's Parliament of Religions in Chicago, introducing aspects of Hindu thought to an international audience.", "region": "india", "topic": "culture", "place": {"name": "Chicago", "lat": 41.88, "lon": -87.63}, "approximate": false},
    {"id": "ramakrishna-mission", "year": 1897, "title": "Ramakrishna Mission founded", "fact": "Swami Vivekananda founded the Ramakrishna Mission, combining spiritual work with education, relief and other service activities.", "region": "india", "topic": "society", "place": {"name": "Kolkata", "lat": 22.57, "lon": 88.36}, "approximate": false},
    {"id": "santiniketan", "year": 1901, "title": "Tagore's school at Santiniketan", "fact": "Rabindranath Tagore founded a school at Santiniketan. It later became part of Visva-Bharati.", "region": "india", "topic": "culture", "place": {"name": "Santiniketan", "lat": 23.68, "lon": 87.68}, "approximate": false},
    {"id": "delhi-capital", "year": 1911, "title": "Transfer of capital to Delhi announced", "fact": "British authorities announced that the capital of British India would move from Calcutta to Delhi. New Delhi was formally inaugurated in 1931.", "region": "india", "topic": "empires", "place": {"name": "Delhi", "lat": 28.61, "lon": 77.21}, "approximate": false},
    {"id": "tagore-nobel", "year": 1913, "title": "Tagore receives Nobel Prize", "fact": "Rabindranath Tagore received the Nobel Prize in Literature, recognised particularly for Gitanjali in its English version.", "region": "india", "topic": "culture", "place": {"name": "Santiniketan", "lat": 23.68, "lon": 87.68}, "approximate": false},
    {"id": "raja-harishchandra", "year": 1913, "title": "Raja Harishchandra released", "fact": "Dadasaheb Phalke's silent film Raja Harishchandra was released in Bombay, a major landmark in Indian feature filmmaking.", "region": "india", "topic": "culture", "place": {"name": "Mumbai", "lat": 19.08, "lon": 72.88}, "approximate": false},
    {"id": "bhu", "year": 1916, "title": "Banaras Hindu University founded", "fact": "Banaras Hindu University was established with Madan Mohan Malaviya as a leading founder and support from several collaborators.", "region": "india", "topic": "culture", "place": {"name": "Varanasi", "lat": 25.32, "lon": 82.97}, "approximate": false},
    {"id": "poona-pact", "year": 1932, "title": "Poona Pact", "fact": "B. R. Ambedkar and other leaders reached an agreement on representation for the communities then officially called the Depressed Classes, replacing a separate-electorate proposal.", "region": "india", "topic": "society", "place": {"name": "Pune", "lat": 18.52, "lon": 73.86}, "approximate": false},
    {"id": "constitution-adopted", "year": 1949, "title": "Constitution of India adopted", "fact": "The Constituent Assembly adopted the Constitution on 26 November. Most of it came into force on 26 January 1950.", "region": "india", "topic": "society", "place": {"name": "Delhi", "lat": 28.61, "lon": 77.21}, "approximate": false},
    {"id": "states-reorganisation", "year": 1956, "title": "States Reorganisation Act", "fact": "India reorganised many state boundaries, largely along linguistic lines, through the States Reorganisation Act and constitutional changes.", "region": "india", "topic": "society", "place": {"name": "Delhi", "lat": 28.61, "lon": 77.21}, "approximate": false},
    {"id": "chipko", "year": 1973, "title": "Chipko protests", "fact": "Villagers in the Himalayan region protested commercial tree felling in actions known as the Chipko movement. Women played prominent roles in its development.", "region": "india", "topic": "society", "place": {"name": "Uttarakhand", "lat": 30.4, "lon": 79.32}, "approximate": false},
    {"id": "aditya-l1", "year": 2024, "title": "Aditya-L1 reaches its halo orbit", "fact": "India's Aditya-L1 solar observatory entered a halo orbit around the Sun–Earth L1 region on 6 January 2024. It studies the Sun from a location about 1.5 million kilometres from Earth.", "region": "india", "topic": "science", "place": {"name": "Bengaluru", "lat": 12.97, "lon": 77.59}, "approximate": false, "sourceURL": "https://www.isro.gov.in/ISRO_EN/halo-orbit-insertion-adtya-l1.html"},
    {"id": "spadex", "year": 2025, "title": "SpaDeX satellites dock in orbit", "fact": "ISRO completed docking of the two SpaDeX satellites on 16 January 2025, demonstrating technology for joining spacecraft in orbit.", "region": "india", "topic": "science", "place": {"name": "Bengaluru", "lat": 12.97, "lon": 77.59}, "approximate": false, "sourceURL": "https://www.isro.gov.in/ISRO_EN/spadex_docking.html"}
